python3 -c "
import math, statistics as st, json
dates=['2026-01-05','2026-01-06','2026-01-07','2026-01-08','2026-01-09','2026-01-12']
c={'AAA':[100.0,101.0,99.5,102.0,103.5,101.0],'BBB':[50.0,50.5,50.75,51.5,52.0,52.25]}
r={t:[math.log(v[i]/v[i-1]) for i in range(1,6)] for t,v in c.items()}
w=2
vol={t:[None if i<w else st.stdev(x[i-w:i])*math.sqrt(252) for i in range(5)] for t,x in r.items()}
print(json.dumps(r)); print(json.dumps(vol))
for t,x in r.items():
  ar=252*st.mean(x); av=math.sqrt(252)*st.stdev(x); print(t, json.dumps([ar,av,ar/av if av else 0.0, vol[t][-1]]))
  wealth=[1.0]; 
  for v in x: wealth.append(wealth[-1]*math.exp(v))
  best=(0.0,0,0); pk=0
  for i,wv in enumerate(wealth):
    if wv>wealth[pk]: pk=i
    d=wv/wealth[pk]-1
    if d<best[0]: best=(d,pk,i)
  print(t, best[0], dates[best[1]], dates[best[2]])
"
